for pert in gene drug; do
for sign in 1 -1; do
(ls ../${pert}_comparisons/ | grep _${sign} | rev | cut -d_ -f2- | rev | sort -u | paste -sd$'\t' | sed 's/_f1_matches/ signature-matching/g' | sed 's/ConnectivityMap_predictions/CMA4/g' | sed 's/SNACKKSS_predictions/SA4/g' | sed 's/_pos/ supportive/g' | sed 's/_neg/ inhibitory/g' | sed 's/_a4c_predictions/ A4C/g' | sed 's/human/Human/g' | sed 's/mouse/Mouse/g' | sed 's/PubTator3_p3a4/P3A4/g' | sed 's/PARMESAN_pa4/PA4/g' | sed 's/_indirect/ indirect/g' | sed 's/_consensus/ consensus/g' | awk '{print "\tNothing\t" $0}'
for i in $(seq 0 99 | awk '{print $1 / 100}'); do echo -n $i$'\t'; for excluded in everything $(ls ../${pert}_comparisons/*_${sign}.txt); do cat $(ls ../${pert}_comparisons/*_${sign}.txt | sed 's/ /\n/g' | grep -vw $excluded | paste -sd' ') | awk '{print $1 "\t" $2 "\t" $3 "\t'$sign'\t" $4}' | sort -k3,3gr -k4,4gr | sort -k1,1 -k2,2 -u | awk '$4 '$sgn' 0' | sort -k3,3gr | awk 'BEGIN {FS = "\t"; cur = ""; p = 0; n = 0} {if(cur != "" && cur != $3 && p+n>0){print cur "\t" p "\t" n "\t" p/(p+n)} cur = $3; if($4 * $5 > 0){p++} else{n++}} END {if(p + n > 0){print cur "\t" p "\t" n "\t" p/(p+n)} print "1\t0\t0\t1"}' | awk '$4 > '$i | sort -k2,2gr | head -1 | cut -f2; done | paste -sd$'\t'
done) > ${pert}_${sign}_unsmoothed_ablation_test.txt &
(ls ../${pert}_comparisons/ | grep _${sign} | rev | cut -d_ -f2- | rev | sort -u | paste -sd$'\t' | sed 's/_f1_matches/ signature-matching/g' | sed 's/ConnectivityMap_predictions/CMA4/g' | sed 's/SNACKKSS_predictions/SA4/g' | sed 's/_pos/ supportive/g' | sed 's/_neg/ inhibitory/g' | sed 's/_a4c_predictions/ A4C/g' | sed 's/human/Human/g' | sed 's/mouse/Mouse/g' | sed 's/PubTator3_p3a4/P3A4/g' | sed 's/PARMESAN_pa4/PA4/g' | sed 's/_indirect/ indirect/g' | sed 's/_consensus/ consensus/g' | awk '{print "\tNothing\t" $0}'
for i in $(seq 0 99 | awk '{print $1 / 100}'); do echo -n $i$'\t'; for excluded in everything $(ls ../${pert}_comparisons/*_${sign}.txt); do cat $(ls ../${pert}_comparisons/*_${sign}.txt | sed 's/ /\n/g' | grep -vw $excluded | paste -sd' ') | awk '{print $1 "\t" $2 "\t" $3 "\t'$sign'\t" $4}' | sort -k3,3gr -k4,4gr | sort -k1,1 -k2,2 -u | awk '$4 '$sgn' 0' | sort -k3,3gr | awk 'BEGIN {FS = "\t"; cur = ""; p = 0; n = 0} {if(cur != "" && cur != $3){print cur "\t" p "\t" n "\t" p/(p+n+1)} cur = $3; if($4 * $5 > 0){p++} else{n++}} END {print cur "\t" p "\t" n "\t" p/(p+n+1); print "1\t0\t0\t1"}' | awk '$4 > '$i | sort -k2,2gr | head -1 | cut -f2; done | paste -sd$'\t'
done) > ${pert}_${sign}_smoothed_ablation_test.txt &
done
done
while [ $(jobs | grep Running | wc -l) -gt 0 ]; do jobs; sleep 1; done

